=== secret-scanner.js ===
#!/usr/bin/env node
/**
 * PreToolUse(Write|Edit|MultiEdit|NotebookEdit) — block writes containing secrets.
 *
 * Adapted from awesome-claude-code-toolkit hooks/scripts/secret-scanner.js (Apache-2.0).
 * Three fixes over the original:
 *   1. Reads hook input from stdin, not process.argv[2] (the original always parsed
 *      "{}" and exited immediately, so it never scanned anything).
 *   2. Scans the *pending* content from tool_input, not the file on disk. The original
 *      read the existing file, so a brand-new secret being written was never seen.
 *   3. Emits hookSpecificOutput.permissionDecision, the format PreToolUse honors.
 */
const path = require("path");

const PATTERNS = [
  { name: "AWS Access Key", regex: /AKIA[0-9A-Z]{16}/ },
  { name: "AWS Secret Key", regex: /aws_secret_access_key\s*=\s*["']?[A-Za-z0-9/+=]{40}/i },
  { name: "GitHub Token", regex: /(ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9_]{36,}/ },
  { name: "Private Key", regex: /-----BEGIN (RSA|EC|OPENSSH|PGP) PRIVATE KEY-----/ },
  { name: "Generic API Key", regex: /api[_-]?key\s*[:=]\s*["'][a-zA-Z0-9]{20,}["']/i },
  { name: "Slack Token", regex: /xox[bpors]-[0-9a-zA-Z-]{10,}/ },
  { name: "Database URL with password", regex: /(postgres|mysql|mongodb|redis):\/\/[^:\s]+:[^@\s]+@/ },
  { name: "JWT", regex: /eyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/ },
  // C-AIMMS-specific: this project holds OpenAI/DeepSeek/Anthropic and HF credentials.
  { name: "OpenAI/Anthropic-style key", regex: /\b(sk-ant-|sk-proj-|sk-)[A-Za-z0-9_-]{20,}/ },
  { name: "HuggingFace token", regex: /\bhf_[A-Za-z0-9]{30,}/ },
];

// Files where a placeholder is expected and a match is not a leak.
const ALLOWLIST = [/\.env\.example$/, /(^|\/)secret-scanner\.js$/, /(^|\/)CLAUDE_TOOLKIT_ANALYSIS\.md$/];

function pendingContent(toolName, ti) {
  if (!ti) return "";
  switch (toolName) {
    case "Write":
      return ti.content || "";
    case "Edit":
      return ti.new_string || "";
    case "MultiEdit":
      return (ti.edits || []).map((e) => e.new_string || "").join("\n");
    case "NotebookEdit":
      return ti.new_source || "";
    default:
      return ti.content || ti.new_string || "";
  }
}

function main(raw) {
  let input;
  try {
    input = JSON.parse(raw || "{}");
  } catch {
    process.exit(0);
  }

  const ti = input.tool_input || {};
  const filePath = ti.file_path || ti.notebook_path || "";
  if (!filePath) process.exit(0);
  if (ALLOWLIST.some((re) => re.test(filePath))) process.exit(0);

  const content = pendingContent(input.tool_name, ti);
  if (!content) process.exit(0);

  const lines = content.split("\n");
  const findings = [];
  for (const { name, regex } of PATTERNS) {
    for (let i = 0; i < lines.length; i++) {
      if (regex.test(lines[i])) findings.push(`line ${i + 1}: ${name}`);
    }
  }

  if (findings.length === 0) process.exit(0);

  const reason =
    `Blocked: potential secret in ${path.basename(filePath)}\n` +
    findings.map((f) => `  - ${f}`).join("\n") +
    `\nPut the value in .env (gitignored) and read it via os.environ, or use a ` +
    `\${ENV_VAR} reference if this is a config file.`;

  process.stdout.write(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "deny",
        permissionDecisionReason: reason,
      },
    })
  );
  process.exit(0);
}

let raw = "";
process.stdin.on("data", (c) => (raw += c));
process.stdin.on("end", () => main(raw));
=== commit-guard.js ===
#!/usr/bin/env node
/**
 * PreToolUse(Bash) — enforce Conventional Commits.
 *
 * Adapted from awesome-claude-code-toolkit hooks/scripts/commit-guard.js (Apache-2.0),
 * fixed to read stdin, to look at tool_input.command, and to emit the PreToolUse
 * hookSpecificOutput format (the original's top-level {"decision":"block"} is the
 * PostToolUse shape and is ignored on PreToolUse).
 *
 * This is load-bearing: /changelog and release-manager parse conventional commits.
 */
const TYPES = "feat|fix|docs|style|refactor|perf|test|chore|ci|build|revert|exp";
const CONVENTIONAL = new RegExp(`^(${TYPES})(\\([^)]+\\))?!?: .+`);

function extractMessages(command) {
  // -m "msg" / -m 'msg' / --message="msg", possibly repeated.
  const out = [];
  const re = /(?:-m|--message)[= ]\s*(["'])([\s\S]*?)\1/g;
  let m;
  while ((m = re.exec(command)) !== null) out.push(m[2]);
  return out;
}

function main(raw) {
  let input;
  try {
    input = JSON.parse(raw || "{}");
  } catch {
    process.exit(0);
  }

  const command = ((input.tool_input || {}).command || "").trim();
  if (!/\bgit\b[^\n]*\bcommit\b/.test(command)) process.exit(0);
  // Amending metadata or committing with an editor/file — nothing to validate here.
  if (/--amend\b/.test(command) && !/-m|--message/.test(command)) process.exit(0);
  if (/-F\b|--file\b/.test(command)) process.exit(0);

  const messages = extractMessages(command);
  if (messages.length === 0) process.exit(0);

  const subject = messages[0].split("\n")[0];
  const errors = [];

  if (!CONVENTIONAL.test(subject)) {
    errors.push(`does not match "type(scope): description" — type must be one of ${TYPES.replace(/\|/g, ", ")}`);
  }
  if (subject.length > 72) errors.push(`subject is ${subject.length} chars (max 72)`);
  if (subject.endsWith(".")) errors.push("subject must not end with a period");

  const desc = subject.replace(new RegExp(`^(${TYPES})(\\([^)]+\\))?!?: `), "");
  if (desc && desc[0] === desc[0].toUpperCase() && /[A-Za-z]/.test(desc[0])) {
    errors.push("description should start lowercase");
  }

  if (errors.length === 0) process.exit(0);

  process.stdout.write(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "deny",
        permissionDecisionReason:
          `Commit message rejected: "${subject}"\n` +
          errors.map((e) => `  - ${e}`).join("\n") +
          `\nExample: feat(retriever): add on-disk qdrant persistence` +
          `\n(use type "exp" for experiment-only changes)`,
      },
    })
  );
  process.exit(0);
}

let raw = "";
process.stdin.on("data", (c) => (raw += c));
process.stdin.on("end", () => main(raw));

